// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient) public {
        // only codeless (EOA-like) recipients: the external call always succeeds,
        // so the reference never reverts and the domain stays wide.
        vm.assume(recipient.code.length == 0);
        vm.assume(recipient != address(0));

        vm.deal(address(c), 1000 ether);
        vm.deal(address(this), 1 ether);

        uint256 bal0 = address(c).balance;

        vm.prank(address(this));
        c.getFirstWithdrawalBonus(recipient);

        uint256 bal1 = address(c).balance;

        vm.prank(address(this));
        c.withdrawReward(recipient);

        uint256 bal2 = address(c).balance;

        // General rule: once withdrawReward succeeded, the recipient's reward is
        // cleared; a repeat withdrawReward succeeds but transfers nothing,
        // so the contract balance is unchanged by the second call.
        assertTrue(bal2 == bal1 && bal1 == bal0 - 100);
    }
}
